head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};


scwin.ccb_checkcombobox1_onviewchange = function(info) {
	debugger;
	alert("info.newInfo[0].label + info.newInfo[0].checked = " + info.newInfo[0].label + info.newInfo[0].checked );
};

	scwin.simulateWrapper = function(target, type, options) {
		$(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#wq_uuid_5_input', 'key-sequence', {
			sequence: '직권'
		});
	}			
	scwin.checkVal1 = function() {
		const td_length = WebSquare.wUnit.getDomById('wq_uuid_5_itemTable_main').querySelectorAll('td').length;

		return td_length == 4;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_5_label').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_5_input').value = '직권'");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_5_input').click()");
		WebSquare.wUnit.addCommand("pause", "400");			
		//WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_cell_0_0').click()");
		WebSquare.wUnit.addCommand("pause", "400");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
